const photoObserver=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){const image=e.target;const picture=image.closest('picture');if(picture)$$('source[data-srcset]',picture).forEach(source=>{source.srcset=source.dataset.srcset;delete source.dataset.srcset});if(image.dataset.srcset){image.srcset=image.dataset.srcset;delete image.dataset.srcset}image.src=image.dataset.src;delete image.dataset.src;photoObserver.unobserve(image)}},{rootMargin:'200px 0px'});
