function view(slug,index=0){const p=posts.get(slug),m=p?.media?.[index];if(!m)return;document.querySelectorAll('video').forEach(v=>v.pause());viewerScale=1;$('.viewer-stage').innerHTML=m.type==='video'?`<video src="${esc(m.url)}" controls playsinline autoplay></video>`:`<img src="${esc(m.large||m.url)}" alt="${esc(m.alt||p.title)}" draggable="false">`;$('.viewer-credit').textContent=[m.alt||p.title,m.credit,m.license,m.date&&date(m.date)].filter(Boolean).join(' · ');viewer.showModal();const im=$('.viewer-stage img');if(im){const pointers=new Map();let distance=0,startScale=1,x=0,y=0,last=null;const apply=()=>{im.style.transform=`translate(${x}px,${y}px) scale(${viewerScale})`};im.onpointerdown=e=>{im.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const [a,b]=[...pointers.values()];distance=Math.hypot(a.x-b.x,a.y-b.y);startScale=viewerScale}last={x:e.clientX,y:e.clientY}};im.onpointermove=e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const[a,b]=[...pointers.values()];viewerScale=Math.max(1,Math.min(5,startScale*Math.hypot(a.x-b.x,a.y-b.y)/distance))}else if(viewerScale>1&&last){x+=e.clientX-last.x;y+=e.clientY-last.y}last={x:e.clientX,y:e.clientY};apply()};im.onpointerup=im.onpointercancel=e=>{pointers.delete(e.pointerId);last=null};im.ondblclick=()=>{viewerScale=viewerScale===1?2:1;x=y=0;apply()};viewer.zoom=(how)=>{viewerScale=how==='reset'?1:Math.max(1,Math.min(5,viewerScale+(how==='in'?.5:-.5)));if(viewerScale===1)x=y=0;apply()}}}
$('.viewer-close').onclick=()=>viewer.close();viewer.addEventListener('close',()=>{$('.viewer-stage').innerHTML='';viewerScale=1;viewer.zoom=null});$$('[data-zoom]').forEach(b=>b.onclick=()=>viewer.zoom?.(b.dataset.zoom));sheet.addEventListener('close',()=>clearInterval(commentTimer));
async function submit(form,fn){const button=$('[type=submit],button:not([type])',form),status=$('.form-status',form);if(button)button.disabled=true;if(status){status.classList.remove('error');status.textContent='Inahifadhi…'}try{const d={};new FormData(form).forEach((v,k)=>d[k]=v);$$('input[type=checkbox]',form).forEach(x=>d[x.name]=x.checked);const r=await fn(d);if(status)status.textContent=r?.message||'Imehifadhiwa.';return r}catch(e){if(status){status.textContent=e.message;status.classList.add('error')}else toast(e.message)}finally{if(button)button.disabled=false}}
